// Collage layout data. Layout sets come from the asset pack (kind "collage", id "grid-<n>", generated by
// scripts/gen-collage.mjs): normalised [x, y, w, h] cell rects for 2..9 photos. Every canvas ratio ("pack") offers
// the same layouts; the pack only changes the canvas ratio.
import { getAssetMeta } from "@/lib/assets";

export type Rect = [number, number, number, number];

/** All layouts for a photo count, in pack order. */
export function templatesFor(count: number): Rect[][] {
  const m = getAssetMeta<{ layouts?: number[][][] }>("collage", `grid-${count}`);
  return (m?.layouts ?? []).map((l) => l.map((v) => [v[0], v[1], v[2], v[3]] as Rect));
}

/** Canvas ratio choice; `icon` is a ratio icon id. */
export interface Pack { id: string; rx: number; ry: number; icon: string; title: string }

export const PACKS: Pack[] = [
  { id: "1_1", rx: 1, ry: 1, icon: "ratio-1-1", title: "1:1" },
  { id: "3_4", rx: 3, ry: 4, icon: "ratio-3-4", title: "3:4" },
  { id: "4_3", rx: 4, ry: 3, icon: "ratio-4-3", title: "4:3" },
  { id: "9_16", rx: 9, ry: 16, icon: "ratio-9-16", title: "9:16" },
  { id: "16_9", rx: 16, ry: 9, icon: "ratio-16-9", title: "16:9" },
];

/** Square canvas for 2 / 3 / 5 / 7 / 8 photos, portrait 3:4 otherwise. */
export function defaultPack(count: number): Pack {
  const want = [2, 3, 5, 7, 8].includes(count) ? "1_1" : "3_4";
  return PACKS.find((p) => p.id === want) ?? PACKS[0];
}

/** Selection: nothing applied yet, a layout (ratio + index), or a vertical / horizontal sequence. */
export type Sel =
  | { kind: "none" }
  | { kind: "layout"; pack: string; index: number }
  | { kind: "height" }
  | { kind: "width" };

/** Layouts and both sequences have an editable border; "none" does not. */
export const borderEditable = (s: Sel) => s.kind !== "none";

/** Border colours: white, black, then a neutral-to-vivid palette. */
export const COMMON_COLORS = [
  "#ffffff", "#000000", "#6b6b6b", "#c4c4c4", "#f7efe2", "#f4dca8", "#f2c14e", "#ef8a3c", "#e4572e", "#d8435f", "#f08fa8",
  "#f6c6d4", "#c9b6e4", "#7e66b3", "#5b3a7e", "#2f4bd8", "#3f8fd2", "#8fd3e6", "#9ed2a2", "#7fb04f", "#2f6b3a", "#14876f",
];
